#Function to Datatype of Date from Object to DateTime
def str_to_datetime(s):
  split = s.split('-')
  year, month, day = int(split[0]), int(split[1]), int(split[2])
  return datetime(year=year, month=month, day=day)

#Converting DataType of Date
